const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taipei = ee.Geometry.Point(121.56, 25.04); // Approximate center of Taipei
  const scale = 1000; // MODIS LST is 1km resolution

  const targetYear = 2016;
  const targetStartDate = `${targetYear}-01-17`;
  const targetEndDate = `${targetYear}-01-24`;

  const refStartYear = 2001;
  const refEndYear = 2010;
  const refMonthDayStart = '01-17';
  const refMonthDayEnd = '01-24';

  const LST_BAND = 'LST_Day_1km';

  // Function to mask clouds and scale LST
  function maskAndScaleLST(image) {
    const lst = image.select(LST_BAND);
    const qc = image.select('QC_Day');

    // LST_Day_1km has fill value 0.
    // QC_Day bits 0-1: LST quality (00 = good, 01 = retrieved, lower quality, 10 = cloudy, 11 = error).
    // QC_Day bits 6-7: Cloud contamination (00 = clear, 01 = cloudy, 10 = mixed, 11 = not set).
    // We want good LST quality (00 or 01) and clear sky (00).

    const lstQuality = qc.rightShift(0).bits(1); // Bits 0-1
    const cloudContamination = qc.rightShift(6).bits(1); // Bits 6-7

    // Keep pixels where LST quality is good (0 or 1) and cloud contamination is clear (0).
    const qualityMask = lstQuality.lte(1).and(cloudContamination.eq(0));

    // Mask out bad quality pixels and fill values (0)
    const maskedLST = lst.updateMask(qualityMask).updateMask(lst.gt(0));

    // Scale LST to Kelvin (0.02 scaling factor for MOD11A1)
    return maskedLST.multiply(0.02).subtract(273.15) // Convert to Celsius for easier interpretation
      .copyProperties(image, ['system:time_start']);
  }

  // 2. Data Acquisition & Check - 2016 Target Period
  let targetCollection = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterBounds(taipei)
    .filterDate(targetStartDate, targetEndDate)
    .map(maskAndScaleLST);

  const targetSize = await targetCollection.size().getInfo();
  if (targetSize === 0) {
    console.log("No images found for 2016 target period.");
    console.log("C1");
    return;
  }

  // Calculate mean LST for 2016
  const targetMeanLSTImage = targetCollection.mean();

  // 3. Data Acquisition & Check - 2001-2010 Reference Period
  let referenceCollection = ee.ImageCollection('MODIS/006/MOD11A1');

  // Filter for each year in the reference period
  let annualCollections = [];
  for (let year = refStartYear; year <= refEndYear; year++) {
    const yearStartDate = `${year}-${refMonthDayStart}`;
    const yearEndDate = `${year}-${refMonthDayEnd}`;
    const yearCollection = referenceCollection
      .filterBounds(taipei)
      .filterDate(yearStartDate, yearEndDate)
      .map(maskAndScaleLST);
    annualCollections.push(yearCollection);
  }

  let mergedReferenceCollection = ee.ImageCollection(annualCollections).flatten();

  const refSize = await mergedReferenceCollection.size().getInfo();
  if (refSize === 0) {
    console.log("No images found for 2001-2010 reference period.");
    console.log("C1");
    return;
  }

  // Calculate mean LST for the reference period
  const refMeanLSTImage = mergedReferenceCollection.mean();

  // 4. Calculate LST values for Taipei
  const getMeanLST = async (image, name) => {
    if (!image) {
        console.log(`Error: ${name} image is null.`);
        return null;
    }
    // Calculate pixel count to detect C2
    const pixelCount = await image.select(LST_BAND).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: taipei,
      scale: scale,
      maxPixels: 1e9
    }).get(LST_BAND).getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels for ${name} after masking.`);
      return { lst: null, pixels: 0 };
    }

    const lstValue = await image.select(LST_BAND).reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: taipei,
      scale: scale,
      maxPixels: 1e9
    }).get(LST_BAND).getInfo();

    return { lst: lstValue, pixels: pixelCount };
  };

  console.log(`2016 Images: ${targetSize}`);
  const targetResult = await getMeanLST(targetMeanLSTImage, '2016');
  if (targetResult === null) return; // Error handled by getMeanLST

  console.log(`2001-2010 Reference Images: ${refSize}`);
  const refResult = await getMeanLST(refMeanLSTImage, '2001-2010 average');
  if (refResult === null) return; // Error handled by getMeanLST

  // Check for C2 after processing
  if (targetResult.pixels === 0 || refResult.pixels === 0) {
    console.log("C2");
    return;
  }

  // Check for C3 if LST values are null/NaN
  if (targetResult.lst === null || isNaN(targetResult.lst) || refResult.lst === null || isNaN(refResult.lst)) {
    console.log("Calculation failure: LST value is None or NaN.");
    console.log("C3");
    return;
  }

  const targetLST = targetResult.lst;
  const refLST = refResult.lst;

  console.log(`2016 (Jan 17-24) LST: ${targetLST.toFixed(2)} C (Pixels: ${targetResult.pixels})`);
  console.log(`2001-2010 Avg (Jan 17-24) LST: ${refLST.toFixed(2)} C (Pixels: ${refResult.pixels})`);

  // 5. Validation & Final Answer
  // Does the LST in Taipei, Taiwan decrease in January 17-24, 2016 compared to the 2001-2010 average?
  if (targetLST < refLST) {
    console.log("A"); // Yes, it decreased
  } else {
    console.log("B"); // No, it did not decrease (either increased or stayed the same)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
